describe('User Logout Functionality', () => {
  beforeEach(() => {
    cy.visit('/login');
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });

  it('should successfully log out a user and redirect to login page', () => {
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="logout-button"]').click();
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');
    cy.wait('@logoutRequest');
    cy.url().should('eq', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="user-menu-button"]').should('not.exist');
    cy.get('[data-testid="logout-message"]').should('contain', 'You have been logged out');
  });

  it('should handle logout when user session is already expired', () => {
    cy.visit('/dashboard');
    cy.intercept('GET', '/api/user/profile', { statusCode: 401, body: { error: 'Session expired' } }).as('expiredSession');
    cy.wait('@expiredSession');
    cy.get('[data-testid="user-menu-button"]').should('be.visible');
    cy.get('[data-testid="logout-button"]').click();
    cy.intercept('POST', '/api/auth/logout').as('logoutRequest');
    cy.wait('@logoutRequest');
    cy.url().should('eq', '/login');
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="logout-message"]').should('contain', 'You have been logged out');
  });
});
